-- British Columbia and Yukon standards. NWT stays coming soon.
-- Not applied to the hosted Supabase project. Apply after review, after 20261018040000.










on conflict (slug) do update set title = excluded.title;

on conflict (skill_id, standard_id) do update set strength = excluded.strength, note = excluded.note;

update public.jurisdiction set publish_status = 'published' where code in ($txt$BC$txt$, $txt$YT$txt$);
