insert into public.standard (doc_id, strand_id, grade, code, code_type, source_system_id, level, parent_id, text, extra, source_url, display_order, needs_review, last_verified)
values
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$big_idea$txt$), 1, $txt$BC-MA-G1-BI01$txt$, $txt$derived$txt$, null, $txt$big_idea$txt$, null, $txt$Numbers to 20 represent quantities that can be decomposed into 10s and 1s.$txt$, $txt${"elaboration":"Number: Number represents and describes quantity. Sample questions to support inquiry with students: How does understanding 5 or 10 help us think about other numbers? What is the relationship between 10s and 1s? Why is it useful to use 10 frames to represent quantities? What stories live in numbers? How do numbers help us communicate and think about place? How do numbers help us communicate and think about ourselves?","seq":1}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/1/core$txt$, 1, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$big_idea$txt$), 1, $txt$BC-MA-G1-BI02$txt$, $txt$derived$txt$, null, $txt$big_idea$txt$, null, $txt$Addition and subtraction with numbers to 10 can be modelled concretely, pictorially, and symbolically to develop computational fluency.$txt$, $txt${"elaboration":"Computational Fluency: Computational fluency develops from a strong sense of number. Sample questions to support inquiry with students: What is the relationship between addition and subtraction? How does knowing that 4 and 6 make 10 help you understand other ways to make 10? How many different ways can you solve…? (e.g., 8 + 5)","seq":2}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/1/core$txt$, 2, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$big_idea$txt$), 1, $txt$BC-MA-G1-BI03$txt$, $txt$derived$txt$, null, $txt$big_idea$txt$, null, $txt$Repeating elements in patterns can be identified.$txt$, $txt${"elaboration":"Patterning: We use patterns to represent identified regularities and to make generalizations. Sample questions to support inquiry with students: How can patterns be used to make predictions? What is the relationship between increasing patterns and addition? What do you notice about this pattern? What is the part that repeats? What number patterns live in a hundred chart?","seq":3}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/1/core$txt$, 3, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$big_idea$txt$), 1, $txt$BC-MA-G1-BI04$txt$, $txt$derived$txt$, null, $txt$big_idea$txt$, null, $txt$Objects and shapes have attributes that can be described, measured, and compared.$txt$, $txt${"elaboration":"Geometry and Measurement: We can describe, measure, and compare spatial relationships. Sample questions to support inquiry with students: How are these shapes alike and different? What stories live in these shapes? What 2D shapes can you find in nature?","seq":4}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/1/core$txt$, 4, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$big_idea$txt$), 1, $txt$BC-MA-G1-BI05$txt$, $txt$derived$txt$, null, $txt$big_idea$txt$, null, $txt$Concrete graphs help us to compare and interpret data and show one-to-one correspondence.$txt$, $txt${"elaboration":"Data and Probability: Analyzing data and chance enables us to compare and interpret. Sample questions to support inquiry with students: What stories can data tell us? When might we use words like never, sometimes, always, more likely, and less likely? How does organizing concrete data help us understand the data?","seq":5}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/1/core$txt$, 5, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$content$txt$), 1, $txt$BC-MA-G1-C01$txt$, $txt$derived$txt$, null, $txt$content$txt$, null, $txt$number concepts to 20$txt$, $txt${"elaboration":"counting: counting on and counting back skip-counting by 2 and 5 sequencing numbers to 20 comparing and ordering numbers to 20 Numbers to 20 can be arranged and recognized. subitizing base 10 10 and some more books published by Native Northwest: Learn to Count, by various artists; Counting Wild Bears, by Gryn White; We All Count, by Jason Adair; We All Count, by Julie Flett (nativenorthwest.com) using counting collections made of local materials; counting in different languages; different First Peoples counting systems (e.g., Tsimshian) Tlingit Math Book (yukon-ed-show-me-your-math.wikispaces.com/file/detail/Tlingit Math Book.pdf)","seq":1}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/1/core$txt$, 6, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$content$txt$), 1, $txt$BC-MA-G1-C02$txt$, $txt$derived$txt$, null, $txt$content$txt$, null, $txt$ways to make 10$txt$, $txt${"elaboration":"decomposing 10 into parts Numbers to 10 can be arranged and recognized. benchmarks of 10 and 20 Traditional First Peoples counting methods involved using fingers to count to 5 and for groups of 5. traditional songs/singing and stories","seq":2}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/1/core$txt$, 7, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$content$txt$), 1, $txt$BC-MA-G1-C03$txt$, $txt$derived$txt$, null, $txt$content$txt$, null, $txt$addition and subtraction to 20 (understanding of operation and process)$txt$, $txt${"elaboration":"decomposing 20 into parts mental math strategies: counting on making 10 doubles Addition and subtraction are related. whole-class number talks nature scavenger hunt in Kaska Counting Book (yukon-ed-show-me-your-math.wikispaces.com/file/detail/Kaska Counting Book.pdf)","seq":3}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/1/core$txt$, 8, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$content$txt$), 1, $txt$BC-MA-G1-C04$txt$, $txt$derived$txt$, null, $txt$content$txt$, null, $txt$repeating patterns with multiple elements and attributes$txt$, $txt${"elaboration":"identifying sorting rules repeating patterns with multiple elements/attributes translating patterns from one representation to another (e.g., an orange-blue pattern could be translated to a circle-square pattern) letter coding of pattern predicting an element in repeating patterns using a variety of strategies patterns using visuals (ten-frames, hundred charts) investigating numerical patterns (e.g., skip-counting by 2s or 5s on a hundred chart) beading using 3–5 colours","seq":4}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/1/core$txt$, 9, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$content$txt$), 1, $txt$BC-MA-G1-C05$txt$, $txt$derived$txt$, null, $txt$content$txt$, null, $txt$change in quantity to 20, concretely and verbally$txt$, $txt${"elaboration":"verbally describing a change in quantity (e.g., I can build 7 and make it 10 by adding 3)","seq":5}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/1/core$txt$, 10, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$content$txt$), 1, $txt$BC-MA-G1-C06$txt$, $txt$derived$txt$, null, $txt$content$txt$, null, $txt$meaning of equality and inequality$txt$, $txt${"elaboration":"demonstrating and explaining the meaning of equality and inequality recording equations symbolically, using = and ≠","seq":6}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/1/core$txt$, 11, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$content$txt$), 1, $txt$BC-MA-G1-C07$txt$, $txt$derived$txt$, null, $txt$content$txt$, null, $txt$direct measurement with non-standard units (non-uniform and uniform)$txt$, $txt${"elaboration":"Non-uniform units are not consistent in size (e.g., children’s hands, pencils); uniform units are consistent in size (e.g., interlocking cubes, standard paper clips). understanding the importance of using a baseline for direct comparison in linear measurement using multiple copies of a unit iterating a single unit for measuring (e.g., to measure the length of a string with only one cube, a student iterates the cube over and over, keeping track of how many cubes long the string is) tiling an area rope knots at intervals using body parts to measure book: An Anishnaabe Look at Measurement, by Rhonda Hopkins and Robin King-Stonefish (strongnations.com/store/item_display.php?i=3494&f=) hand/foot tracing for mitten/moccasin making","seq":7}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/1/core$txt$, 12, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$content$txt$), 1, $txt$BC-MA-G1-C08$txt$, $txt$derived$txt$, null, $txt$content$txt$, null, $txt$comparison of 2D shapes and 3D objects$txt$, $txt${"elaboration":"sorting 3D objects and 2D shapes using one attribute, and explaining the sorting rule comparing 2D shapes and 3D objects in the environment describing relative positions, using positional language (e.g., up and down, in and out) replicating composite 2D shapes and 3D objects (e.g., putting two triangles together to make a square)","seq":8}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/1/core$txt$, 13, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$content$txt$), 1, $txt$BC-MA-G1-C09$txt$, $txt$derived$txt$, null, $txt$content$txt$, null, $txt$concrete graphs, using one-to-one correspondence$txt$, $txt${"elaboration":"creating, describing, and comparing concrete graphs","seq":9}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/1/core$txt$, 14, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$content$txt$), 1, $txt$BC-MA-G1-C10$txt$, $txt$derived$txt$, null, $txt$content$txt$, null, $txt$likelihood of familiar life events, using comparative language$txt$, $txt${"elaboration":"using the language of probability (e.g., never, sometimes, always, more likely, less likely) cycles (Elder or knowledge keeper to speak about ceremonies and life events)","seq":10}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/1/core$txt$, 15, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$content$txt$), 1, $txt$BC-MA-G1-C11$txt$, $txt$derived$txt$, null, $txt$content$txt$, null, $txt$financial literacy — values of coins, and monetary exchanges$txt$, $txt${"elaboration":"identifying values of coins (nickels, dimes, quarters, loonies, and toonies) counting multiples of the same denomination (nickels, dimes, loonies, and toonies) Money is a medium of exchange. role-playing financial transactions (e.g., using coins and whole numbers), integrating the concept of wants and needs trade games, with understanding that objects have variable value or worth (shells, beads, furs, tools)","seq":11}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/1/core$txt$, 16, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$competency$txt$), 1, $txt$BC-MA-G1-CC01$txt$, $txt$derived$txt$, null, $txt$competency$txt$, null, $txt$Use reasoning to explore and make connections$txt$, $txt${"group":"Reasoning and analyzing","seq":1}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/1/core$txt$, 17, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$competency$txt$), 1, $txt$BC-MA-G1-CC02$txt$, $txt$derived$txt$, null, $txt$competency$txt$, null, $txt$Estimate reasonably$txt$, $txt${"elaboration":"estimating by comparing to something familiar (e.g., more than 5, taller than me) First Peoples people used specific estimating and measuring techniques in daily life (e.g., estimating time using environmental references and natural daily/seasonal cycles, estimating temperatures based on weather systems).","group":"Reasoning and analyzing","seq":2}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/1/core$txt$, 18, false, $txt$2026-10-17$txt$::date),
