  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$competency$txt$), 1, $txt$BC-MA-G1-CC15$txt$, $txt$derived$txt$, null, $txt$competency$txt$, null, $txt$Connect mathematical concepts to each other and to other areas and personal interests$txt$, $txt${"elaboration":"to develop a sense of how mathematics helps us understand ourselves and the world around us (e.g., daily activities, local and traditional practices, the environment, popular media and news events, social justice, and cross-curricular integration)","group":"Connecting and reflecting","seq":15}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/1/core$txt$, 31, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$competency$txt$), 1, $txt$BC-MA-G1-CC16$txt$, $txt$derived$txt$, null, $txt$competency$txt$, null, $txt$Incorporate First Peoples worldviews and perspectives to make connections to mathematical concepts$txt$, $txt${"elaboration":"how an ovoid has a different look to represent different animal parts Invite local First Peoples Elders and knowledge keepers to share their knowledge. || Bishop’s cultural practices: counting, measuring, locating, designing, playing, explaining (csus.edu/indiv/o/oreyd/ACP.htm_files/abishop.htm) aboriginaleducation.ca Teaching Mathematics in a First Nations Context, FNESC fnesc.ca/k-7/","group":"Connecting and reflecting","seq":16}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/1/core$txt$, 32, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$big_idea$txt$), 2, $txt$BC-MA-G2-BI01$txt$, $txt$derived$txt$, null, $txt$big_idea$txt$, null, $txt$Numbers to 100 represent quantities that can be decomposed into 10s and 1s.$txt$, $txt${"elaboration":"Number: Number represents and describes quantity. Sample questions to support inquiry with students: How does understanding 5 or 10 help us think about other numbers? What is the relationship between 10s and 1s? What patterns do you notice in numbers? What stories live in numbers? How do numbers help us communicate and think about place? How do numbers help us communicate and think about ourselves?","seq":1}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/2/core$txt$, 1, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$big_idea$txt$), 2, $txt$BC-MA-G2-BI02$txt$, $txt$derived$txt$, null, $txt$big_idea$txt$, null, $txt$Development of computational fluency in addition and subtraction with numbers to 100 requires an understanding of place value.$txt$, $txt${"elaboration":"Computational Fluency: Computational fluency develops from a strong sense of number. Sample questions to support inquiry with students: What is the relationship between addition and subtraction? How can you use addition to help you subtract? How does understanding 10 help us to add and subtract two-digit numbers?","seq":2}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/2/core$txt$, 2, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$big_idea$txt$), 2, $txt$BC-MA-G2-BI03$txt$, $txt$derived$txt$, null, $txt$big_idea$txt$, null, $txt$The regular change in increasing patterns can be identified and used to make generalizations.$txt$, $txt${"elaboration":"Patterning: We use patterns to represent identified regularities and to make generalizations. Sample questions to support inquiry with students: How can we represent patterns in different ways/modes? How can you create repeating patterns with objects that are all one colour? What stories live in patterns?","seq":3}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/2/core$txt$, 3, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$big_idea$txt$), 2, $txt$BC-MA-G2-BI04$txt$, $txt$derived$txt$, null, $txt$big_idea$txt$, null, $txt$Objects and shapes have attributes that can be described, measured, and compared.$txt$, $txt${"elaboration":"Geometry and Measurement: We can describe, measure, and compare spatial relationships. Sample questions to support inquiry with students: What 2D shapes live in objects in our world? How can you combine shapes to make new shapes?","seq":4}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/2/core$txt$, 4, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$big_idea$txt$), 2, $txt$BC-MA-G2-BI05$txt$, $txt$derived$txt$, null, $txt$big_idea$txt$, null, $txt$Concrete items can be represented, compared, and interpreted pictorially in graphs.$txt$, $txt${"elaboration":"Data and Probability: Analyzing data and chance enables us to compare and interpret. Sample questions to support inquiry with students: When you look at this graph, what do you notice? What do you wonder? How do graphs help us understand data? What are some different ways to represent data pictorially?","seq":5}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/2/core$txt$, 5, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$content$txt$), 2, $txt$BC-MA-G2-C01$txt$, $txt$derived$txt$, null, $txt$content$txt$, null, $txt$number concepts to 100$txt$, $txt${"elaboration":"counting: skip-counting by 2, 5, and 10: using different starting points increasing and decreasing (forward and backward) Quantities to 100 can be arranged and recognized: comparing and ordering numbers to 100 benchmarks of 25, 50, and 100 place value: understanding of 10s and 1s understanding the relationship between digit places and their value, to 99 (e.g., the digit 4 in 49 has the value of 40) decomposing two-digit numbers into 10s and 1s even and odd numbers","seq":1}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/2/core$txt$, 6, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$content$txt$), 2, $txt$BC-MA-G2-C02$txt$, $txt$derived$txt$, null, $txt$content$txt$, null, $txt$benchmarks of 25, 50, and 100 and personal referents$txt$, $txt${"elaboration":"seating arrangements at ceremonies/feasts","seq":2}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/2/core$txt$, 7, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$content$txt$), 2, $txt$BC-MA-G2-C03$txt$, $txt$derived$txt$, null, $txt$content$txt$, null, $txt$addition and subtraction facts to 20 (introduction of computational strategies)$txt$, $txt${"elaboration":"adding and subtracting numbers to 20 fluency with math strategies for addition and subtraction (e.g., making or bridging 10, decomposing, identifying related doubles, adding on to find the difference)","seq":3}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/2/core$txt$, 8, false, $txt$2026-10-17$txt$::date);
insert into public.standard (doc_id, strand_id, grade, code, code_type, source_system_id, level, parent_id, text, extra, source_url, display_order, needs_review, last_verified)
values
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$content$txt$), 2, $txt$BC-MA-G2-C04$txt$, $txt$derived$txt$, null, $txt$content$txt$, null, $txt$addition and subtraction to 100$txt$, $txt${"elaboration":"decomposing numbers to 100 estimating sums and differences to 100 using strategies such as looking for multiples of 10, friendly numbers (e.g., 48 + 37, 37 = 35 + 2, 48 + 2 = 50, 50 + 35 = 85), decomposing into 10s and 1s and recomposing (e.g., 48 + 37, 40 + 30 = 70, 8 +7 = 15, 70 +15 = 85), and compensating (e.g., 48 + 37, 48 +2 = 50, 37 – 2 = 35, 50 + 35 = 80) adding up to find the difference using an open number line, hundred chart, ten-frames using addition and subtraction in real-life contexts and problem-based situations whole-class number talks","seq":4}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/2/core$txt$, 9, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$content$txt$), 2, $txt$BC-MA-G2-C05$txt$, $txt$derived$txt$, null, $txt$content$txt$, null, $txt$repeating and increasing patterns$txt$, $txt${"elaboration":"exploring more complex repeating patterns (e.g., positional patterns, circular patterns) identifying the core of repeating patterns (e.g., the pattern of the pattern that repeats over and over) increasing patterns using manipulatives, sounds, actions, and numbers (0 to 100) Métis finger weaving First Peoples head/armband patterning online video and text: Small Number Counts to 100 (mathcatcher.irmacs.sfu.ca/story/small-number-counts-100)","seq":5}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/2/core$txt$, 10, false, $txt$2026-10-17$txt$::date),
