  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$competency$txt$), 2, $txt$BC-MA-G2-CC12$txt$, $txt$derived$txt$, null, $txt$competency$txt$, null, $txt$Explain and justify mathematical ideas and decisions$txt$, $txt${"elaboration":"using mathematical arguments “Prove it!”","group":"Communicating and representing","seq":12}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/2/core$txt$, 29, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$competency$txt$), 2, $txt$BC-MA-G2-CC13$txt$, $txt$derived$txt$, null, $txt$competency$txt$, null, $txt$Represent mathematical ideas in concrete, pictorial, and symbolic forms$txt$, $txt${"elaboration":"Use local materials gathered outside for concrete and pictorial representations.","group":"Communicating and representing","seq":13}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/2/core$txt$, 30, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$competency$txt$), 2, $txt$BC-MA-G2-CC14$txt$, $txt$derived$txt$, null, $txt$competency$txt$, null, $txt$Reflect on mathematical thinking$txt$, $txt${"elaboration":"sharing the mathematical thinking of self and others, including evaluating strategies and solutions, extending, and posing new problems and questions","group":"Connecting and reflecting","seq":14}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/2/core$txt$, 31, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$competency$txt$), 2, $txt$BC-MA-G2-CC15$txt$, $txt$derived$txt$, null, $txt$competency$txt$, null, $txt$Connect mathematical concepts to each other and to other areas and personal interests$txt$, $txt${"elaboration":"to develop a sense of how mathematics helps us understand ourselves and the world around us (e.g., daily activities, local and traditional practices, the environment, popular media and news events, social justice, and cross-curricular integration)","group":"Connecting and reflecting","seq":15}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/2/core$txt$, 32, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$competency$txt$), 2, $txt$BC-MA-G2-CC16$txt$, $txt$derived$txt$, null, $txt$competency$txt$, null, $txt$Incorporate First Peoples worldviews and perspectives to make connections to mathematical concepts$txt$, $txt${"elaboration":"Invite local First Peoples Elders and knowledge keepers to share their knowledge. || Bishop’s cultural practices: counting, measuring, locating, designing, playing, explaining (csus.edu/indiv/o/oreyd/ACP.htm_files/abishop.htm) aboriginaleducation.ca Teaching Mathematics in a First Nations Context, FNESC fnesc.ca/k-7/","group":"Connecting and reflecting","seq":16}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/2/core$txt$, 33, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$big_idea$txt$), 3, $txt$BC-MA-G3-BI01$txt$, $txt$derived$txt$, null, $txt$big_idea$txt$, null, $txt$Fractions are a type of number that can represent quantities.$txt$, $txt${"elaboration":"Number: Number represents and describes quantity. Sample questions to support inquiry with students: In how many ways can you represent the fraction ____? What is the relationship between parts and wholes when we think about fractions? How do these materials help you think about fractions? What stories live in numbers? How do numbers help us communicate and think about place? How do numbers help us communicate and think about ourselves?","seq":1}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/3/core$txt$, 1, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$big_idea$txt$), 3, $txt$BC-MA-G3-BI02$txt$, $txt$derived$txt$, null, $txt$big_idea$txt$, null, $txt$Development of computational fluency in addition, subtraction, multiplication, and division of whole numbers requires flexible decomposing and composing.$txt$, $txt${"elaboration":"Computational Fluency: Computational fluency develops from a strong sense of number. Sample questions to support inquiry with students: What is the relationship between addition and multiplication? How can we decompose and compose numbers to help us add, subtract, multiply, and divide? How might we use mental math strategies to solve equations?","seq":2}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/3/core$txt$, 2, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$big_idea$txt$), 3, $txt$BC-MA-G3-BI03$txt$, $txt$derived$txt$, null, $txt$big_idea$txt$, null, $txt$Regular increases and decreases in patterns can be identified and used to make generalizations.$txt$, $txt${"elaboration":"Patterning: We use patterns to represent identified regularities and to make generalizations. Sample questions to support inquiry with students: How are these patterns alike and different (e.g., increasing and decreasing)? How are place value patterns repeated in large numbers? How do numbers help us describe patterns?","seq":3}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/3/core$txt$, 3, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$big_idea$txt$), 3, $txt$BC-MA-G3-BI04$txt$, $txt$derived$txt$, null, $txt$big_idea$txt$, null, $txt$Standard units are used to describe, measure, and compare attributes of objects’ shapes.$txt$, $txt${"elaboration":"Geometry and Measurement: We can describe, measure, and compare spatial relationships. Sample questions to support inquiry with students: Where do 2D shapes live in 3D objects? How do standard units help us to compare and communicate measurements? How do the properties of shapes contribute to buildings and designs?","seq":4}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/3/core$txt$, 4, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$big_idea$txt$), 3, $txt$BC-MA-G3-BI05$txt$, $txt$derived$txt$, null, $txt$big_idea$txt$, null, $txt$The likelihood of possible outcomes can be examined, compared, and interpreted.$txt$, $txt${"elaboration":"Data and Probability: Analyzing data and chance enables us to compare and interpret. Sample questions to support inquiry with students: How is the probability of an event determined and described? What events in our lives are left to chance? What are the possible outcomes of these events?","seq":5}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/3/core$txt$, 5, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$content$txt$), 3, $txt$BC-MA-G3-C01$txt$, $txt$derived$txt$, null, $txt$content$txt$, null, $txt$number concepts to 1000$txt$, $txt${"elaboration":"counting: skip-counting by any number from any starting point, increasing and decreasing (i.e., forward and backward) skip-counting is related to multiplication investigating place-value based counting patterns (e.g., counting by 10s, 100s; bridging over a century; noticing the role of zero as a placeholder 698, 699, 700, 701; noticing the predictability of our number system) Numbers to 1000 can be arranged and recognized: comparing and ordering numbers estimating large quantities place value: 100s, 10s, and 1s understanding the relationship between digit places and their values, to 1000 (e.g., the digit 4 in 342 has the value of 40 or 4 tens) understanding the importance of 0 as a place holder (e.g., in the number 408, the zero indicates that there are 0 tens) instructional resource: Math in a Cultural Context, by Jerry Lipka","seq":1}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/3/core$txt$, 6, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$content$txt$), 3, $txt$BC-MA-G3-C02$txt$, $txt$derived$txt$, null, $txt$content$txt$, null, $txt$fraction concepts$txt$, $txt${"elaboration":"Fractions are numbers that represent an amount or quantity. Fractions can represent parts of a region, set, or linear model. Fraction parts are equal shares or equal-sized portions of a whole or unit. Provide opportunities to explore and create fractions with concrete materials. recording pictorial representations of fraction models and connecting to symbolic notation equal partitioning equal sharing, pole ratios as visual parts, medicine wheel, seasons","seq":2}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/3/core$txt$, 7, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$content$txt$), 3, $txt$BC-MA-G3-C03$txt$, $txt$derived$txt$, null, $txt$content$txt$, null, $txt$addition and subtraction to 1000$txt$, $txt${"elaboration":"using flexible computation strategies, involving taking apart (e.g., decomposing using friendly numbers and compensating) and combining numbers in a variety of ways, regrouping estimating sums and differences of all operations to 1000 using addition and subtraction in real-life contexts and problem-based situations whole-class number talks","seq":3}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/3/core$txt$, 8, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$content$txt$), 3, $txt$BC-MA-G3-C04$txt$, $txt$derived$txt$, null, $txt$content$txt$, null, $txt$addition and subtraction facts to 20 (emerging computational fluency)$txt$, $txt${"elaboration":"adding and subtracting of numbers to 20 demonstrating fluency with math strategies for addition and subtraction (e.g., decomposing, making and bridging 10, related doubles, and commutative property) Addition and subtraction are related. At the end of Grade 3, most students should be able to recall addition facts to 20.","seq":4}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/3/core$txt$, 9, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$content$txt$), 3, $txt$BC-MA-G3-C05$txt$, $txt$derived$txt$, null, $txt$content$txt$, null, $txt$multiplication and division concepts$txt$, $txt${"elaboration":"understanding concepts of multiplication (e.g., groups of, arrays, repeated addition) understanding concepts of division (e.g., sharing, grouping, repeated subtraction) Multiplication and division are related. Provide opportunities for concrete and pictorial representations of multiplication. Use games to develop opportunities for authentic practice of multiplication computations. looking for patterns in numbers, such as in a hundred chart, to further develop understanding of multiplication computation Connect multiplication to skip-counting. Connect multiplication to division and repeated addition. Memorization of facts is not intended for this level. fish drying on rack; sharing of food resources in First Peoples communities","seq":5}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/3/core$txt$, 10, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$content$txt$), 3, $txt$BC-MA-G3-C06$txt$, $txt$derived$txt$, null, $txt$content$txt$, null, $txt$increasing and decreasing patterns$txt$, $txt${"elaboration":"creating patterns using concrete, pictorial, and numerical representations representing increasing and decreasing patterns in multiple ways generalizing what makes the pattern increase or decrease (e.g., doubling, adding 2)","seq":6}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/3/core$txt$, 11, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$content$txt$), 3, $txt$BC-MA-G3-C07$txt$, $txt$derived$txt$, null, $txt$content$txt$, null, $txt$pattern rules using words and numbers, based on concrete experiences$txt$, $txt${"elaboration":"from a concrete pattern, describing the pattern rule using words and numbers predictability in song rhythm and patterns Share examples of local First Peoples art with the class, and ask students to notice patterns in the artwork.","seq":7}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/3/core$txt$, 12, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$content$txt$), 3, $txt$BC-MA-G3-C08$txt$, $txt$derived$txt$, null, $txt$content$txt$, null, $txt$one-step addition and subtraction equations with an unknown number$txt$, $txt${"elaboration":"start unknown (e.g., n + 15 = 20 or □ + 15 + 20) change unknown ( e.g., 12 + n = 20 or 12 + □ = 20) result unknown (e.g., 6 + 13 = n or 6 + 13 = □;) investigating even and odd numbers","seq":8}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/3/core$txt$, 13, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$content$txt$), 3, $txt$BC-MA-G3-C09$txt$, $txt$derived$txt$, null, $txt$content$txt$, null, $txt$measurement, using standard units (linear, mass, and capacity)$txt$, $txt${"elaboration":"linear measurements, using standard units (e.g., centimetre, metre, kilometre) capacity measurements, using standard units (e.g., millilitre, litre) Introduce concepts of perimeter, area, and circumference (the distance around); use of formula and pi to calculate not intended — the focus is on the concepts. area measurement, using square units (standard and non-standard) mass measurements, using standard units (e.g., gram, kilogram) estimation of measurements, using standard referents (e.g., If this cup holds 100 millilitres, about how much does this jug hold?)","seq":9}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/3/core$txt$, 14, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$content$txt$), 3, $txt$BC-MA-G3-C10$txt$, $txt$derived$txt$, null, $txt$content$txt$, null, $txt$time concepts$txt$, $txt${"elaboration":"understanding concepts of time (e.g., second, minute, hour, day, week, month, year) understanding the relationships between units of time Telling time is not expected at this level. estimating time, using environmental references and natural daily/seasonal cycles, temperatures based on weather systems, traditional calendar","seq":10}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/3/core$txt$, 15, false, $txt$2026-10-17$txt$::date);
insert into public.standard (doc_id, strand_id, grade, code, code_type, source_system_id, level, parent_id, text, extra, source_url, display_order, needs_review, last_verified)
values
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$content$txt$), 3, $txt$BC-MA-G3-C11$txt$, $txt$derived$txt$, null, $txt$content$txt$, null, $txt$construction of 3D objects$txt$, $txt${"elaboration":"identifying 3D objects according to the 2D shapes of the faces and the number of edges and vertices (e.g., construction of nets, skeletons) describing the attributes of 3D objects (e.g., faces, edges, vertices) identifying 3D objects by their mathematical terms (e.g., sphere, cube, prism, cone, cylinder) comparing 3D objects (e.g., How are rectangular prisms and cubes the same or different?) understanding the preservation of shape (e.g., the orientation of a shape will not change its properties) jingle dress bells, bentwood box, birch bark baskets, pithouses","seq":11}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/3/core$txt$, 16, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$content$txt$), 3, $txt$BC-MA-G3-C12$txt$, $txt$derived$txt$, null, $txt$content$txt$, null, $txt$one-to-one correspondence with bar graphs, pictographs, charts, and tables$txt$, $txt${"elaboration":"collecting data, creating a graph, and describing, comparing, and discussing the results choosing a suitable representation","seq":12}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/3/core$txt$, 17, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$content$txt$), 3, $txt$BC-MA-G3-C13$txt$, $txt$derived$txt$, null, $txt$content$txt$, null, $txt$likelihood of simulated events, using comparative language$txt$, $txt${"elaboration":"using comparative language (e.g., certain, uncertain; more, less, or equally likely) developing an understanding of chance (e.g., tossing a coin creates a 50-50 chance of landing a head or tail; drawing from a bag, using spinners, and rolling dice all simulate probability events) story: The Snowsnake Game (yukon-ed-show-me-your-math.wikispaces.com/file/view/The%20Snowsnake%20Game.pdf/203828506/The%20Snowsnake%20Game.pdf)","seq":13}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/3/core$txt$, 18, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$content$txt$), 3, $txt$BC-MA-G3-C14$txt$, $txt$derived$txt$, null, $txt$content$txt$, null, $txt$financial literacy — fluency with coins and bills to 100 dollars, and earning and payment$txt$, $txt${"elaboration":"counting mixed combinations of coins and bills up to $100: totalling up a set of coins and bills using different combinations of coins and bills to make the same amount understanding that payments can be made in flexible ways (e.g., cash, cheques, credit, electronic transactions, goods and services) understanding that there are different ways of earning money to reach a financial goal (e.g., recycling, holding bake sales, selling items, walking a neighbour’s dog) Using pictures of First Peoples trade items (e.g., dentalium shells, dried fish, or tools when available) with the values indicated on the back, have students play a trading game.","seq":14}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/3/core$txt$, 19, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$competency$txt$), 3, $txt$BC-MA-G3-CC01$txt$, $txt$derived$txt$, null, $txt$competency$txt$, null, $txt$Use reasoning to explore and make connections$txt$, $txt${"group":"Reasoning and analyzing","seq":1}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/3/core$txt$, 20, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$competency$txt$), 3, $txt$BC-MA-G3-CC02$txt$, $txt$derived$txt$, null, $txt$competency$txt$, null, $txt$Estimate reasonably$txt$, $txt${"elaboration":"estimating by comparing to something familiar (e.g., more than 5, taller than me)","group":"Reasoning and analyzing","seq":2}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/3/core$txt$, 21, false, $txt$2026-10-17$txt$::date),
