  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$competency$txt$), 3, $txt$BC-MA-G3-CC14$txt$, $txt$derived$txt$, null, $txt$competency$txt$, null, $txt$Reflect on mathematical thinking$txt$, $txt${"elaboration":"sharing the mathematical thinking of self and others, including evaluating strategies and solutions, extending, and posing new problems and questions","group":"Connecting and reflecting","seq":14}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/3/core$txt$, 33, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$competency$txt$), 3, $txt$BC-MA-G3-CC15$txt$, $txt$derived$txt$, null, $txt$competency$txt$, null, $txt$Connect mathematical concepts to each other and to other areas and personal interests$txt$, $txt${"elaboration":"to develop a sense of how mathematics helps us understand ourselves and the world around us (e.g., daily activities, local and traditional practices, the environment, popular media and news events, social justice, and cross-curricular integration)","group":"Connecting and reflecting","seq":15}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/3/core$txt$, 34, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$competency$txt$), 3, $txt$BC-MA-G3-CC16$txt$, $txt$derived$txt$, null, $txt$competency$txt$, null, $txt$Incorporate First Peoples worldviews and perspectives to make connections to mathematical concepts$txt$, $txt${"elaboration":"Invite local First Peoples Elders and knowledge keepers to share their knowledge. || Bishop’s cultural practices: counting, measuring, locating, designing, playing, explaining (csus.edu/indiv/o/oreyd/ACP.htm_files/abishop.htm) aboriginaleducation.ca Teaching Mathematics in a First Nations Context, FNESC fnesc.ca/k-7/","group":"Connecting and reflecting","seq":16}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/3/core$txt$, 35, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$big_idea$txt$), 4, $txt$BC-MA-G4-BI01$txt$, $txt$derived$txt$, null, $txt$big_idea$txt$, null, $txt$Fractions and decimals are types of numbers that can represent quantities.$txt$, $txt${"elaboration":"Number: Number represents and describes quantity. Sample questions to support inquiry with students: What is the relationship between fractions and decimals? How are these fractions (e.g., 1/2 and 7/8) alike and different? How do we use fractions and decimals in our daily life? What stories live in numbers? How do numbers help us communicate and think about place? How do numbers help us communicate and think about ourselves?","nt_flag":"NWT uses BC curriculum for grades 4-9: verify implementation status before publishing under /nwt","seq":1}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/4/core$txt$, 1, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$big_idea$txt$), 4, $txt$BC-MA-G4-BI02$txt$, $txt$derived$txt$, null, $txt$big_idea$txt$, null, $txt$Development of computational fluency and multiplicative thinking requires analysis of patterns and relations in multiplication and division.$txt$, $txt${"elaboration":"Computational Fluency: Computational fluency develops from a strong sense of number. Sample questions to support inquiry with students: What is the relationship between multiplication and division? What patterns in our number system connect to our understanding of multiplication? How does fluency with basic multiplication facts (e.g., 2x, 3x, 5x) help us compute more complex multiplication facts?","nt_flag":"NWT uses BC curriculum for grades 4-9: verify implementation status before publishing under /nwt","seq":2}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/4/core$txt$, 2, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$big_idea$txt$), 4, $txt$BC-MA-G4-BI03$txt$, $txt$derived$txt$, null, $txt$big_idea$txt$, null, $txt$Regular changes in patterns can be identified and represented using tools and tables.$txt$, $txt${"elaboration":"Patterning: We use patterns to represent identified regularities and to make generalizations. Sample questions to support inquiry with students: What regularities can you identify in these patterns? Where do we see patterns in the world around us? How can we represent increasing and decreasing regularities that we see in number patterns? How do tables and charts help us understand number patterns?","nt_flag":"NWT uses BC curriculum for grades 4-9: verify implementation status before publishing under /nwt","seq":3}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/4/core$txt$, 3, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$big_idea$txt$), 4, $txt$BC-MA-G4-BI04$txt$, $txt$derived$txt$, null, $txt$big_idea$txt$, null, $txt$Polygons are closed shapes with similar attributes that can be described, measured, and compared.$txt$, $txt${"elaboration":"Geometry and Measurement: We can describe, measure, and compare spatial relationships. Sample questions to support inquiry with students: How are these polygons alike and different? How can we measure polygons? How do the properties of shapes contribute to buildings and design?","nt_flag":"NWT uses BC curriculum for grades 4-9: verify implementation status before publishing under /nwt","seq":4}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/4/core$txt$, 4, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$big_idea$txt$), 4, $txt$BC-MA-G4-BI05$txt$, $txt$derived$txt$, null, $txt$big_idea$txt$, null, $txt$Analyzing and interpreting experiments in data probability develops an understanding of chance.$txt$, $txt${"elaboration":"Data and Probability: Analyzing data and chance enables us to compare and interpret. Sample questions to support inquiry with students: How is the probability of an event determined and described? What events in our lives are left to chance? How do probability experiments help us understand chance?","nt_flag":"NWT uses BC curriculum for grades 4-9: verify implementation status before publishing under /nwt","seq":5}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/4/core$txt$, 5, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$content$txt$), 4, $txt$BC-MA-G4-C01$txt$, $txt$derived$txt$, null, $txt$content$txt$, null, $txt$number concepts to 10 000$txt$, $txt${"elaboration":"counting: multiples flexible counting strategies whole number benchmarks Numbers to 10 000 can be arranged and recognized: comparing and ordering numbers estimating large quantities place value: 1000s, 100s, 10s, and 1s understanding the relationship between digit places and their value, to 10 000","nt_flag":"NWT uses BC curriculum for grades 4-9: verify implementation status before publishing under /nwt","seq":1}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/4/core$txt$, 6, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$content$txt$), 4, $txt$BC-MA-G4-C02$txt$, $txt$derived$txt$, null, $txt$content$txt$, null, $txt$decimals to hundredths$txt$, $txt${"elaboration":"Fractions and decimals are numbers that represent an amount or quantity. Fractions and decimals can represent parts of a region, set, or linear model. Fractional parts and decimals are equal shares or equal-sized portions of a whole or unit. understanding the relationship between fractions and decimals","nt_flag":"NWT uses BC curriculum for grades 4-9: verify implementation status before publishing under /nwt","seq":2}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/4/core$txt$, 7, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$content$txt$), 4, $txt$BC-MA-G4-C03$txt$, $txt$derived$txt$, null, $txt$content$txt$, null, $txt$ordering and comparing fractions$txt$, $txt${"elaboration":"comparing and ordering of fractions with common denominators estimating fractions with benchmarks (e.g., zero, half, whole) using concrete and visual models equal partitioning","nt_flag":"NWT uses BC curriculum for grades 4-9: verify implementation status before publishing under /nwt","seq":3}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/4/core$txt$, 8, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$content$txt$), 4, $txt$BC-MA-G4-C04$txt$, $txt$derived$txt$, null, $txt$content$txt$, null, $txt$addition and subtraction to 10 000$txt$, $txt${"elaboration":"using flexible computation strategies, involving taking apart (e.g., decomposing using friendly numbers and compensating) and combining numbers in a variety of ways, regrouping estimating sums and differences to 10 000 using addition and subtraction in real-life contexts and problem-based situations whole-class number talks","nt_flag":"NWT uses BC curriculum for grades 4-9: verify implementation status before publishing under /nwt","seq":4}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/4/core$txt$, 9, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$content$txt$), 4, $txt$BC-MA-G4-C05$txt$, $txt$derived$txt$, null, $txt$content$txt$, null, $txt$multiplication and division of two- or three-digit numbers by one-digit numbers$txt$, $txt${"elaboration":"understanding the relationships between multiplication and division, multiplication and addition, division and subtraction using flexible computation strategies (e.g., decomposing, distributive principle, commutative principle, repeated addition and repeated subtraction) using multiplication and division in real-life contexts and problem-based situations whole-class number talks","nt_flag":"NWT uses BC curriculum for grades 4-9: verify implementation status before publishing under /nwt","seq":5}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/4/core$txt$, 10, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$content$txt$), 4, $txt$BC-MA-G4-C06$txt$, $txt$derived$txt$, null, $txt$content$txt$, null, $txt$addition and subtraction of decimals to hundredths$txt$, $txt${"elaboration":"estimating decimal sums and differences using visual models, such as base 10 blocks, place-value mats, grid paper, and number lines using addition and subtraction in real-life contexts and problem-based situations whole-class number talks","nt_flag":"NWT uses BC curriculum for grades 4-9: verify implementation status before publishing under /nwt","seq":6}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/4/core$txt$, 11, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$content$txt$), 4, $txt$BC-MA-G4-C07$txt$, $txt$derived$txt$, null, $txt$content$txt$, null, $txt$addition and subtraction facts to 20 (developing computational fluency)$txt$, $txt${"elaboration":"Provide opportunities for authentic practice, building on previous grade-level addition and subtraction facts. flexible use of mental math strategies","nt_flag":"NWT uses BC curriculum for grades 4-9: verify implementation status before publishing under /nwt","seq":7}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/4/core$txt$, 12, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$content$txt$), 4, $txt$BC-MA-G4-C08$txt$, $txt$derived$txt$, null, $txt$content$txt$, null, $txt$multiplication and division facts to 100 (introductory computational strategies)$txt$, $txt${"elaboration":"Provide opportunities for concrete and pictorial representations of multiplication. building computational fluency Use games to provide opportunities for authentic practice of multiplication computations. looking for patterns in numbers, such as in a hundred chart, to further develop understanding of multiplication computation Connect multiplication to skip-counting. Connecting multiplication to division and repeated addition. Memorization of facts is not intended for this level. Students will become more fluent with these facts. using mental math strategies, such as doubling or halving Students should be able to recall the following multiplication facts by the end of Grade 4 (2s, 5s, 10s).","nt_flag":"NWT uses BC curriculum for grades 4-9: verify implementation status before publishing under /nwt","seq":8}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/4/core$txt$, 13, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$content$txt$), 4, $txt$BC-MA-G4-C09$txt$, $txt$derived$txt$, null, $txt$content$txt$, null, $txt$increasing and decreasing patterns, using tables and charts$txt$, $txt${"elaboration":"Change in patterns can be represented in charts, graphs, and tables. using words and numbers to describe increasing and decreasing patterns fish stocks in lakes, life expectancies","nt_flag":"NWT uses BC curriculum for grades 4-9: verify implementation status before publishing under /nwt","seq":9}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/4/core$txt$, 14, false, $txt$2026-10-17$txt$::date),
