  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$competency$txt$), 4, $txt$BC-MA-G4-CC14$txt$, $txt$derived$txt$, null, $txt$competency$txt$, null, $txt$Reflect on mathematical thinking$txt$, $txt${"elaboration":"sharing the mathematical thinking of self and others, including evaluating strategies and solutions, extending, and posing new problems and questions","group":"Connecting and reflecting","nt_flag":"NWT uses BC curriculum for grades 4-9: verify implementation status before publishing under /nwt","seq":14}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/4/core$txt$, 37, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$competency$txt$), 4, $txt$BC-MA-G4-CC15$txt$, $txt$derived$txt$, null, $txt$competency$txt$, null, $txt$Connect mathematical concepts to each other and to other areas and personal interests$txt$, $txt${"elaboration":"to develop a sense of how mathematics helps us understand ourselves and the world around us (e.g., daily activities, local and traditional practices, the environment, popular media and news events, social justice, and cross-curricular integration)","group":"Connecting and reflecting","nt_flag":"NWT uses BC curriculum for grades 4-9: verify implementation status before publishing under /nwt","seq":15}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/4/core$txt$, 38, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$competency$txt$), 4, $txt$BC-MA-G4-CC16$txt$, $txt$derived$txt$, null, $txt$competency$txt$, null, $txt$Incorporate First Peoples worldviews and perspectives to make connections to mathematical concepts$txt$, $txt${"elaboration":"Invite local First Peoples Elders and knowledge keepers to share their knowledge. || Bishop’s cultural practices: counting, measuring, locating, designing, playing, explaining (csus.edu/indiv/o/oreyd/ACP.htm_files/abishop.htm) aboriginaleducation.ca Teaching Mathematics in a First Nations Context, FNESC fnesc.ca/k-7/","group":"Connecting and reflecting","nt_flag":"NWT uses BC curriculum for grades 4-9: verify implementation status before publishing under /nwt","seq":16}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/4/core$txt$, 39, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$big_idea$txt$), 5, $txt$BC-MA-G5-BI01$txt$, $txt$derived$txt$, null, $txt$big_idea$txt$, null, $txt$Numbers describe quantities that can be represented by equivalent fractions.$txt$, $txt${"elaboration":"Number: Number represents and describes quantity. Sample questions to support inquiry with students: How can you prove that two fractions are equivalent? In how many ways can you represent the fraction ___? How do we use fractions and decimals in our daily life? What stories live in numbers? How do numbers help us communicate and think about place? How do numbers help us communicate and think about ourselves?","nt_flag":"NWT uses BC curriculum for grades 4-9: verify implementation status before publishing under /nwt","seq":1}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/5/core$txt$, 1, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$big_idea$txt$), 5, $txt$BC-MA-G5-BI02$txt$, $txt$derived$txt$, null, $txt$big_idea$txt$, null, $txt$Computational fluency and flexibility with numbers extend to operations with larger (multi-digit) numbers.$txt$, $txt${"elaboration":"Computational Fluency: Computational fluency develops from a strong sense of number. Sample questions to support inquiry with students: How many different ways can you solve…? (e.g., 16 x 7) What flexible strategies can we apply to use operations with multi-digit numbers? How does fluency with basic multiplication facts (e.g., 2x, 3x, 5x) help us compute more complex multiplication facts?","nt_flag":"NWT uses BC curriculum for grades 4-9: verify implementation status before publishing under /nwt","seq":2}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/5/core$txt$, 2, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$big_idea$txt$), 5, $txt$BC-MA-G5-BI03$txt$, $txt$derived$txt$, null, $txt$big_idea$txt$, null, $txt$Identified regularities in number patterns can be expressed in tables.$txt$, $txt${"elaboration":"Patterning: We use patterns to represent identified regularities and to make generalizations. Sample questions to support inquiry with students: How do tables and charts help us understand number patterns? How do tables help us see the relationship between a variable within number patterns? How do rules for increasing and decreasing patterns help us solve equations?","nt_flag":"NWT uses BC curriculum for grades 4-9: verify implementation status before publishing under /nwt","seq":3}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/5/core$txt$, 3, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$big_idea$txt$), 5, $txt$BC-MA-G5-BI04$txt$, $txt$derived$txt$, null, $txt$big_idea$txt$, null, $txt$Closed shapes have area and perimeter that can be described, measured, and compared.$txt$, $txt${"elaboration":"Geometry and Measurement: We can describe, measure, and compare spatial relationships. Sample questions to support inquiry with students: What is the relationship between area and perimeter? What standard units do we use to measure area and perimeter? When might an understanding of area and perimeter be useful?","nt_flag":"NWT uses BC curriculum for grades 4-9: verify implementation status before publishing under /nwt","seq":4}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/5/core$txt$, 4, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$big_idea$txt$), 5, $txt$BC-MA-G5-BI05$txt$, $txt$derived$txt$, null, $txt$big_idea$txt$, null, $txt$Data represented in graphs can be used to show many-to-one correspondence.$txt$, $txt${"elaboration":"Data and Probability: Analyzing data and chance enables us to compare and interpret. Sample questions to support inquiry with students: How do graphs help us understand data? In what different ways can we represent many-to-one correspondence in a graph? Why would you choose many-to-one correspondence rather than one-to-one correspondence in a graph?","nt_flag":"NWT uses BC curriculum for grades 4-9: verify implementation status before publishing under /nwt","seq":5}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/5/core$txt$, 5, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$content$txt$), 5, $txt$BC-MA-G5-C01$txt$, $txt$derived$txt$, null, $txt$content$txt$, null, $txt$number concepts to 1 000 000$txt$, $txt${"elaboration":"counting: multiples flexible counting strategies whole number benchmarks Numbers to 1 000 000 can be arranged and recognized: comparing and ordering numbers estimating large quantities place value: 100 000s, 10 000s, 1000s, 100s, 10s, and 1s understanding the relationship between digit places and their value, to 1 000 000 First Peoples use unique counting systems (e.g., Tsimshian use of three counting systems, for animals, people and things; Tlingit counting for the naming of numbers e.g., 10 = two hands, 20 = one person)","nt_flag":"NWT uses BC curriculum for grades 4-9: verify implementation status before publishing under /nwt","seq":1}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/5/core$txt$, 6, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$content$txt$), 5, $txt$BC-MA-G5-C02$txt$, $txt$derived$txt$, null, $txt$content$txt$, null, $txt$decimals to thousandths$txt$, $txt${"nt_flag":"NWT uses BC curriculum for grades 4-9: verify implementation status before publishing under /nwt","seq":2}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/5/core$txt$, 7, false, $txt$2026-10-17$txt$::date),
