  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$content$txt$), 5, $txt$BC-MA-G5-C04$txt$, $txt$derived$txt$, null, $txt$content$txt$, null, $txt$whole-number, fraction, and decimal benchmarks$txt$, $txt${"elaboration":"Two equivalent fractions are two ways to represent the same amount (having the same whole). comparing and ordering of fractions and decimals addition and subtraction of decimals to thousandths estimating decimal sums and differences estimating fractions with benchmarks (e.g., zero, half, whole) equal partitioning","nt_flag":"NWT uses BC curriculum for grades 4-9: verify implementation status before publishing under /nwt","seq":4}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/5/core$txt$, 9, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$content$txt$), 5, $txt$BC-MA-G5-C05$txt$, $txt$derived$txt$, null, $txt$content$txt$, null, $txt$addition and subtraction of whole numbers to 1 000 000$txt$, $txt${"elaboration":"using flexible computation strategies involving taking apart (e.g., decomposing using friendly numbers and compensating) and combining numbers in a variety of ways, regrouping estimating sums and differences to 10 000 using addition and subtraction in real-life contexts and problem-based situations whole-class number talks","nt_flag":"NWT uses BC curriculum for grades 4-9: verify implementation status before publishing under /nwt","seq":5}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/5/core$txt$, 10, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$content$txt$), 5, $txt$BC-MA-G5-C06$txt$, $txt$derived$txt$, null, $txt$content$txt$, null, $txt$multiplication and division to three digits, including division with remainders$txt$, $txt${"elaboration":"understanding the relationships between multiplication and division, multiplication and addition, and division and subtraction using flexible computation strategies (e.g., decomposing, distributive principle, commutative principle, repeated addition, repeated subtraction) using multiplication and division in real-life contexts and problem-based situations whole-class number talks","nt_flag":"NWT uses BC curriculum for grades 4-9: verify implementation status before publishing under /nwt","seq":6}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/5/core$txt$, 11, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$content$txt$), 5, $txt$BC-MA-G5-C07$txt$, $txt$derived$txt$, null, $txt$content$txt$, null, $txt$addition and subtraction of decimals to thousandths$txt$, $txt${"elaboration":"estimating decimal sums and differences using visual models such as base 10 blocks, place-value mats, grid paper, and number lines using addition and subtraction in real-life contexts and problem-based situations whole-class number talks","nt_flag":"NWT uses BC curriculum for grades 4-9: verify implementation status before publishing under /nwt","seq":7}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/5/core$txt$, 12, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$content$txt$), 5, $txt$BC-MA-G5-C08$txt$, $txt$derived$txt$, null, $txt$content$txt$, null, $txt$addition and subtraction facts to 20 (extending computational fluency)$txt$, $txt${"elaboration":"Provide opportunities for authentic practice, building on previous grade-level addition and subtraction facts. applying strategies and knowledge of addition and subtraction facts in real-life contexts and problem-based situations, as well as when making math-to-math connections (e.g., for 800 + 700, you can annex the zeros and use the knowledge of 8 + 7 to find the total)","nt_flag":"NWT uses BC curriculum for grades 4-9: verify implementation status before publishing under /nwt","seq":8}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/5/core$txt$, 13, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$content$txt$), 5, $txt$BC-MA-G5-C09$txt$, $txt$derived$txt$, null, $txt$content$txt$, null, $txt$multiplication and division facts to 100 (emerging computational fluency)$txt$, $txt${"elaboration":"Provide opportunities for concrete and pictorial representations of multiplication. Use games to provide opportunities for authentic practice of multiplication computations. looking for patterns in numbers, such as in a hundred chart, to further develop understanding of multiplication computation Connect multiplication to skip-counting. Connect multiplication to division and repeated addition. Memorization of facts is not intended this level. Students will become more fluent with these facts. using mental math strategies such as doubling and halving, annexing, and distributive property Students should be able to recall many multiplication facts by the end of Grade 5 (e.g., 2s, 3s, 4s, 5s, 10s). developing computational fluency with facts to 100","nt_flag":"NWT uses BC curriculum for grades 4-9: verify implementation status before publishing under /nwt","seq":9}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/5/core$txt$, 14, false, $txt$2026-10-17$txt$::date),
