  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$competency$txt$), 5, $txt$BC-MA-G5-CC15$txt$, $txt$derived$txt$, null, $txt$competency$txt$, null, $txt$Connect mathematical concepts to each other and to other areas and personal interests$txt$, $txt${"elaboration":"to develop a sense of how mathematics helps us understand ourselves and the world around us (e.g., daily activities, local and traditional practices, the environment, popular media and news events, social justice, and cross-curricular integration)","group":"Connecting and reflecting","nt_flag":"NWT uses BC curriculum for grades 4-9: verify implementation status before publishing under /nwt","seq":15}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/5/core$txt$, 39, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$competency$txt$), 5, $txt$BC-MA-G5-CC16$txt$, $txt$derived$txt$, null, $txt$competency$txt$, null, $txt$Incorporate First Peoples worldviews and perspectives to make connections to mathematical concepts$txt$, $txt${"elaboration":"Invite local First Peoples Elders and knowledge keepers to share their knowledge. || Bishop’s cultural practices: counting, measuring, locating, designing, playing, explaining (csus.edu/indiv/o/oreyd/ACP.htm_files/abishop.htm) aboriginaleducation.ca Teaching Mathematics in a First Nations Context, FNESC fnesc.ca/k-7/","group":"Connecting and reflecting","nt_flag":"NWT uses BC curriculum for grades 4-9: verify implementation status before publishing under /nwt","seq":16}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/5/core$txt$, 40, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$big_idea$txt$), 6, $txt$BC-MA-G6-BI01$txt$, $txt$derived$txt$, null, $txt$big_idea$txt$, null, $txt$Mixed numbers and decimal numbers represent quantities that can be decomposed into parts and wholes.$txt$, $txt${"elaboration":"Number: Number represents and describes quantity. Sample questions to support inquiry with students: In how many ways can you represent the number ___? What are the connections between fractions, mixed numbers, and decimal numbers? How are mixed numbers and decimal numbers alike? Different?","nt_flag":"NWT uses BC curriculum for grades 4-9: verify implementation status before publishing under /nwt","seq":1}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/6/core$txt$, 1, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$big_idea$txt$), 6, $txt$BC-MA-G6-BI02$txt$, $txt$derived$txt$, null, $txt$big_idea$txt$, null, $txt$Computational fluency and flexibility with numbers extend to operations with whole numbers and decimals.$txt$, $txt${"elaboration":"Computational Fluency: Computational fluency develops from a strong sense of number. Sample questions to support inquiry with students: When we are working with decimal numbers, what is the relationship between addition and subtraction? When we are working with decimal numbers, what is the relationship between multiplication and division? When we are working with decimal numbers, what is the relationship between addition and multiplication? When we are working with decimal numbers, what is the relationship between subtraction and division?","nt_flag":"NWT uses BC curriculum for grades 4-9: verify implementation status before publishing under /nwt","seq":2}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/6/core$txt$, 2, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$big_idea$txt$), 6, $txt$BC-MA-G6-BI03$txt$, $txt$derived$txt$, null, $txt$big_idea$txt$, null, $txt$Linear relations can be identified and represented using expressions with variables and line graphs and can be used to form generalizations.$txt$, $txt${"elaboration":"Patterning: We use patterns to represent identified regularities and to make generalizations. Sample questions to support inquiry with students: What is a linear relationship? How do linear expressions and line graphs represent linear relations? What factors can change or alter a linear relationship?","nt_flag":"NWT uses BC curriculum for grades 4-9: verify implementation status before publishing under /nwt","seq":3}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/6/core$txt$, 3, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$big_idea$txt$), 6, $txt$BC-MA-G6-BI04$txt$, $txt$derived$txt$, null, $txt$big_idea$txt$, null, $txt$Properties of objects and shapes can be described, measured, and compared using volume, area, perimeter, and angles.$txt$, $txt${"elaboration":"Geometry and Measurement: We can describe, measure, and compare spatial relationships. Sample questions to support inquiry with students: How are the areas of triangles, parallelogram, and trapezoids interrelated? What factors are considered when selecting a viable referent in measurement?","nt_flag":"NWT uses BC curriculum for grades 4-9: verify implementation status before publishing under /nwt","seq":4}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/6/core$txt$, 4, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$big_idea$txt$), 6, $txt$BC-MA-G6-BI05$txt$, $txt$derived$txt$, null, $txt$big_idea$txt$, null, $txt$Data from the results of an experiment can be used to predict the theoretical probability of an event and to compare and interpret.$txt$, $txt${"elaboration":"Data and Probability: Analyzing data and chance enables us to compare and interpret. Sample questions to support inquiry with students: What is the relationship between theoretical and experimental probability? What informs our predictions? What factors would influence the theoretical probability of an experiment?","nt_flag":"NWT uses BC curriculum for grades 4-9: verify implementation status before publishing under /nwt","seq":5}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/6/core$txt$, 5, false, $txt$2026-10-17$txt$::date),
