  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$competency$txt$), 7, $txt$BC-MA-G7-CC18$txt$, $txt$derived$txt$, null, $txt$competency$txt$, null, $txt$Incorporate First Peoples worldviews and perspectives to make connections to mathematical concepts$txt$, $txt${"elaboration":"Invite local First Peoples Elders and knowledge keepers to share their knowledge || Bishop’s cultural practices: counting, measuring, locating, designing, playing, explaining (csus.edu/indiv/o/oreyd/ACP.htm_files/abishop.htm) aboriginaleducation.ca Teaching Mathematics in a First Nations Context, FNESC fnesc.ca/k-7/","group":"Connecting and reflecting","nt_flag":"NWT uses BC curriculum for grades 4-9: verify implementation status before publishing under /nwt","seq":18}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/7/core$txt$, 36, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$big_idea$txt$), 8, $txt$BC-MA-G8-BI01$txt$, $txt$derived$txt$, null, $txt$big_idea$txt$, null, $txt$Number represents, describes, and compares the quantities of ratios, rates, and percents.$txt$, $txt${"elaboration":"Number: Number represents and describes quantity. Sample questions to support inquiry with students: How can two quantities be compared, represented, and communicated? How are decimals, fractions, ratios, and percents interrelated? How does ratio use in mechanics differ from ratio use in architecture?","nt_flag":"NWT uses BC curriculum for grades 4-9: verify implementation status before publishing under /nwt","seq":1}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/8/core$txt$, 1, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$big_idea$txt$), 8, $txt$BC-MA-G8-BI02$txt$, $txt$derived$txt$, null, $txt$big_idea$txt$, null, $txt$Computational fluency and flexibility extend to operations with fractions.$txt$, $txt${"elaboration":"Computational Fluency: Computational fluency develops from a strong sense of number. Sample questions to support inquiry with students: When we are working with fractions, what is the relationship between addition and subtraction? When we are working with fractions, what is the relationship between multiplication and division? When we are working with fractions, what is the relationship between addition and multiplication? When we are working with fractions, what is the relationship between subtraction and division?","nt_flag":"NWT uses BC curriculum for grades 4-9: verify implementation status before publishing under /nwt","seq":2}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/8/core$txt$, 2, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$big_idea$txt$), 8, $txt$BC-MA-G8-BI03$txt$, $txt$derived$txt$, null, $txt$big_idea$txt$, null, $txt$Discrete linear relationships can be represented in many connected ways and used to identify and make generalizations.$txt$, $txt${"elaboration":"Patterning: We use patterns to represent identified regularities and to make generalizations. Sample questions to support inquiry with students: What is a discrete linear relationship? How can discrete linear relationships be represented? What factors can change a discrete linear relationship?","nt_flag":"NWT uses BC curriculum for grades 4-9: verify implementation status before publishing under /nwt","seq":3}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/8/core$txt$, 3, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$BC-MATH-K9-2016$txt$) and code = $txt$big_idea$txt$), 8, $txt$BC-MA-G8-BI04$txt$, $txt$derived$txt$, null, $txt$big_idea$txt$, null, $txt$The relationship between surface area and volume of 3D objects can be used to describe, measure, and compare spatial relationships.$txt$, $txt${"elaboration":"Geometry and Measurement: We can describe, measure, and compare spatial relationships. Sample questions to support inquiry with students: What is the relationship between the surface area and volume of regular solids? How can surface area and volume of regular solids be determined? How are the surface area and volume of regular solids related? How does surface area compare with volume in patterning and cubes?","nt_flag":"NWT uses BC curriculum for grades 4-9: verify implementation status before publishing under /nwt","seq":4}$txt$::jsonb, $txt$https://curriculum.gov.bc.ca/curriculum/mathematics/8/core$txt$, 4, false, $txt$2026-10-17$txt$::date),
